-- 5009 🏋️ Exercises from the book "pep-guardiola-85-passing-rondos-possession-games-technical-circuits-direct-from-" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'pep-guardiola-85-passing-rondos-possession-games-technical-circuits-direct-from-');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('One-touch combinations with aerial pass circuit', 'passing_unopposed', 'passive', 'in_possession', 11, 11, 'Training Warm-up Exercises 1', 'Guardiola (Man City)', 'Quick one-touch combination play and a lofted pass to a runner, mixed with light movement work.', 'Two mirrored lanes, each with hurdles, a central side-step channel, mannequins and positions A, B, C, D up the field; coach with balls in the middle, a passive presser near C.', 'Two A players hold hands and side-step through a channel, then hop over hurdles; the coach feeds A, who plays a 1-2 with B and lofts a ball to C. C sets back to B, B slips the ball beyond the mannequin for C, and C finds D to feet or in space; D dribbles back through poles to the start.', 'Mostly one-touch; players rotate A to B to C to D to A.', NULL, 'Sharp one-touch weight, time runs beyond the mannequin, accurate lofted pass.', 'about 12-14 players in two groups', NULL, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 10),
  ('Speed, agility and technique warm-up circuit', 'warm_up', 'unopposed', NULL, 12, 13, 'Training Warm-up Exercises 2', 'Guardiola (Man City)', 'Footwork, agility and change of direction warm-up that adds a ball in later rounds.', 'A loop of speed rings, a side-step/high-knee lane, low hurdles, poles and mannequins; one or two coaches with balls on the outside.', 'Round 1 (no ball): quick single steps through the rings, side-steps or high knees, same-leg steps over 4 low hurdles, feint past a mannequin and run back. Round 2 adds a pass from the coach to dribble through poles, a pass to a team-mate and a dribble round the mannequin. Round 3 swaps that for a 1-2 with a second coach, receiving beyond the mannequin, then dribbling back.', 'Players change rotation direction between rounds (anti-clockwise, clockwise, anti-clockwise).', 'Three variations: no ball; receive-dribble-pass-follow; receive and 1-2 with coach then dribble home.', 'Light quick feet, sharp feint, clean first touch out of the footwork.', 'whole squad in a single file loop', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 20),
  ('Agility circuit then 5v2 rondos', 'warm_up', 'unopposed', NULL, 14, 15, 'Training Warm-up Exercises 3', 'Guardiola (Man City)', 'Activation and mobility circuit leading straight into 5v2 rondos.', 'Groups of 5 on cones round a mannequin, poles, speed rings, cones and low hurdles; rondo grids marked out along the touchline. Keepers work separately with coaches on catching.', 'Groups first do 2 minutes of movement drills round a mannequin and cone (skips, heel flicks, high knees, Brazilian steps, side-steps, jockeying, over-the-gate), then 1.5 min stretching. Next a clockwise circuit: run round the mannequin between stations of side-steps through poles, backwards steps through cones, quick steps in rings and alternate steps over hurdles; 30 s stretch, then repeat anti-clockwise faster. Finish with 5v2 rondos in the grids.', 'Timings: 2 min drills + 1.5 min stretch; circuit 1 min, 30 s stretch, 45 s faster reverse; rondos 7+ minutes.', 'Part 2 repeats the circuit in the opposite direction at a higher pace.', NULL, 'groups of 5; rondos 5v2', NULL, NULL, NULL, NULL, NULL, 12.0, false, true, false, NULL, 30),
  ('Pre-match free individual movement', 'warm_up', 'unopposed', NULL, 17, 17, 'Man City Pre-Match Warm-up Part 1/5', 'Guardiola (Man City)', 'Loose individual activation as players first come out before the team warm-up.', '10 outfield players spread across half the pitch; keepers in the box with the GK coach.', 'For about 2 minutes outfielders do their own general movements such as knee lifts and side-steps. Keepers meanwhile take turns catching crosses from the GK coach.', NULL, NULL, NULL, '10 outfield + GKs', NULL, NULL, NULL, NULL, NULL, 2.0, true, true, false, NULL, 40),
  ('Pre-match bands and dynamic stretching', 'warm_up', 'unopposed', NULL, 18, 18, 'Man City Pre-Match Warm-up Part 2/5', 'Guardiola (Man City)', 'Muscle activation with resistance bands followed by dynamic mobility.', 'Players gathered in a loose circle near the halfway area, each with a mini band.', '1 minute with a band above the knee (twists, squats, diagonal steps, turns) and around the ankles (lateral and backward steps, hops). Then 4 minutes without bands moving out from and back into the circle: leg swings, high knees, skips, heel kicks, side-steps, Brazilian steps, over-the-gate, quad and groin stretches, mobility and hop-and-hold work.', NULL, NULL, NULL, '10 outfield players', NULL, NULL, NULL, NULL, NULL, 5.0, false, false, false, NULL, 50),
  ('4v4 plus 3 jokers pre-match rondo', 'rondo', 'overload', 'in_possession', 19, 19, 'Man City Pre-Match Warm-up Part 3/5', 'Guardiola (Man City)', 'Sharp possession under pressure using numerical superiority, with instant role swap on a turnover.', '12 x 15 yard box; team in possession of 4 placed on the long sides (2 each side), 4 defenders inside, 3 jokers (one at each end, one inside).', 'The outside team plus jokers keep the ball 7v4 against the 4 inside. If the inside team win it they swap places with the outside team and try to keep it themselves.', '3-4 sets of 1 minute with 30 seconds rest; jokers always play for the side with the ball.', NULL, NULL, '4v4+3', 11, 11, '12 x 15 yards', 13.7, 11.0, 6.0, false, false, false, NULL, 60),
  ('Pre-match passing, heading and finishing', 'finishing', 'passive', 'in_possession', 20, 20, 'Man City Pre-Match Warm-up Part 4/5', 'Guardiola (Man City)', 'Position-specific final touches before kick-off: finishing for attackers, passing for midfielders, long passing and heading for defenders.', 'Attackers around the box with a coach and a keeper; two midfielders in the centre circle area; back line deeper with a coach.', 'Front 3 plus the attacking midfielder finish from the coach''s varied lay-offs (to the side, under pressure, bouncing). The two central midfielders pass to each other. The 4 defenders open with long passes, then centre backs and right back head short balls back to the coach while the left back passes with the coach, runs onto a long ball, then dribbles at the coach who jockeys him for a few seconds.', NULL, NULL, NULL, 'starting XI by unit + coaches + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Pre-match sprints in pairs', 'conditioning', 'unopposed', NULL, 21, 21, 'Man City Pre-Match Warm-up Part 5/5', 'Guardiola (Man City)', 'Final speed primer before leaving the pitch.', 'Players in pairs near a touchline cone with the coach a few yards away.', 'Pairs do four quick movements each followed by a sprint past the coach: high knees, jumping twists, facing and jumping as if to head, then side-on step back and turn into a long sprint to halfway, after which they leave the pitch.', NULL, NULL, NULL, 'pairs', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 80),
  ('Hurdle jumps and resistance band sprints', 'conditioning', 'unopposed', NULL, 23, 23, 'Speed & Agility WITHOUT a Ball 1', 'Guardiola (Man City)', 'Explosive power, landing control and acceleration.', 'Group 1 at a line of low hurdles; group 2 lines with coaches holding resistance bands round the players'' waists, cones out to the side and ahead.', 'Group 1: two-footed jump over hurdle one then sideways, forward over the second, sideways over the third and back, then sprint. Group 2: sprint sideways against the band, return, repeat the other way, return, then sprint forward with the coach letting go of the band halfway.', NULL, NULL, 'Soft bouncy landings between hurdles; drive hard when the band is released.', 'two groups', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 90),
  ('Footwork stations into sprints', 'conditioning', 'unopposed', NULL, 24, 24, 'Speed & Agility WITHOUT a Ball 2', 'Guardiola (Man City)', 'Coordination and quick feet followed by straight-line acceleration.', 'Four parallel lanes, each with a different footwork set-up (low hurdles with flat markers, speed rings, ground poles plus hurdle, offset left/right hurdles) and a cone gate further on.', 'Lane 1: sideways over hurdles pausing on each marker. Lane 2: quick free feet through the rings. Lane 3: sideways through poles, forward and back over a pole, two-footed jump over a hurdle. Lane 4: two steps between hurdles with single-foot steps over side hurdles. Every lane ends with a sprint through the cone gate.', NULL, NULL, NULL, 'four groups', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 100),
  ('Footwork stations with angled sprints', 'conditioning', 'unopposed', NULL, 25, 25, 'Speed & Agility WITHOUT a Ball 3', 'Guardiola (Bayern Munich)', 'Agility then sprinting on diagonal and straight lines.', 'Three lanes: cones plus speed rings; low yellow and red hurdles; two speed ladders in an L, with cone gates and white cones as sprint targets.', 'Group 1 side-steps between cones, quick steps through rings, then sprints diagonally to one cone and forward to another. Group 2 side-steps over low hurdles, steps forward over one more, then sprints short diagonal or long straight. Group 3 goes forward through one ladder, sideways through part of the second, then sprints diagonally through the far gate.', NULL, 'Group 3 variation: forward through the ladder, 180-degree spin, diagonal sprint through the gate.', NULL, 'three groups', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 110),
  ('Double one-two and long-range shot', 'combination', 'unopposed', 'in_possession', 27, 27, 'Speed & Agility WITH a Ball 1', 'Guardiola (Barcelona B)', 'Combination play and shooting from distance under physical load.', 'Mirrored on both sides of the pitch: A players on the halfway line, B just outside the box, with hurdles, red ground poles and blue slalom poles between; keeper in goal.', 'A plays long to B, hops two hurdles and strides through the ground poles; B returns the ball. A gives it back and slaloms the blue poles, B slips it inside and A shoots from outside the box.', 'Each rep about 9-10 seconds; 2 x 8 minute sets with 2 minutes rest; rotate A to B to A.', NULL, NULL, 'two groups A/B + GK', NULL, NULL, 'half pitch', NULL, NULL, 18.0, true, true, true, NULL, 120),
  ('Dribble, long pass, one-two and shoot', 'combination', 'unopposed', 'in_possession', 28, 28, 'Speed & Agility WITH a Ball 2', 'Guardiola (Barcelona B)', 'Dribbling, long passing and a return combination finished from range, with agility work between.', 'Both flanks: A at the halfway line with balls and cones to dribble through, B groups at the edge of the box, red ground poles, blue poles and cones between; keeper in goal.', 'A dribbles through cones, plays long to B, then runs round a cone, strides through ground poles and slaloms the blue poles. B returns, A plays back and loops round a cone, B lays it into A''s path and A shoots from outside the box.', '3 reps each side (6 shots) = 1 set; 2 sets, 3 minutes rest; after 3 reps players switch sides.', NULL, NULL, 'two groups A/B + GK', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Agility, double one-two, two shots', 'combination', 'unopposed', 'in_possession', 29, 29, 'Speed & Agility WITH a Ball 3', 'Guardiola (Barcelona B)', 'Changes of direction combined with one-twos and finishing for both players.', 'Mirrored on both sides: ground poles, blue poles, mannequins at the top of the D; B players inside the box, coaches with balls by the posts; keeper.', 'A strides through ground poles and weaves the first blue poles, receives from B and returns, works across and back through more poles and ground poles, then plays a 1-2 with B and runs round the mannequin to shoot from outside the box. The coach then gives B a new ball to drive in and score.', '3 reps each side = 1 set; 2 sets, 3 min rest; rotate A to B to A.', NULL, NULL, 'two groups A/B + GK + 2 coaches', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Dribble, pass wide, cross and finish', 'finishing', 'unopposed', 'in_possession', 30, 30, 'Speed & Agility WITH a Ball 4', 'Guardiola (Barcelona B)', 'Wide combination and crossing to a late run, with conditioning loads.', 'A in the centre circle, B on the right touchline near halfway, hurdles, ground poles and mannequins in between; keeper in goal.', 'A does 5 sit-ups and dribbles through poles while B does 5 weight reps; A passes to B, who has jumped two hurdles, rounded a pole and striden through ground poles. B plays it ahead for A over hurdles, A sends it wide for B to run onto high up the flank, and B crosses for A who has curled round the mannequin into the box.', 'Set 1 = 4 laps, set 2 = 3 laps with distances cut by 20%; 3 min rest.', NULL, NULL, 'pairs A/B + GK', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Lay-off, wide pass, cross for two runners', 'finishing', 'unopposed', 'in_possession', 31, 31, 'Speed & Agility WITH a Ball 5', 'Guardiola (Barcelona B)', 'Lay-off, switch to the wing and cross for two attackers arriving in the box.', 'Four positions: A deep centrally, B on the far flank, C near the D, D at the edge of the box by hurdles; mannequins, hurdles; keeper.', 'A does weight reps and passes to B; B hops two hurdles and runs round a mannequin while C does medicine-ball reps. B plays forward to C, who drops and lays off for A. A sends it wide for B high on the flank; C curves into the box and D hops hurdles and attacks the box too. B crosses, C and D try to score.', '2 sets of 4 reps, 3 min rest; rotate A to B to C to D to A; switch sides after 2 reps.', NULL, NULL, 'groups of 4 + GK', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Lay-off, wide pass, dribble, cross', 'finishing', 'unopposed', 'in_possession', 32, 32, 'Speed & Agility WITH a Ball 6', 'Guardiola (Barcelona B)', 'Three-player build-out to the wing finished from a cross, with conditioning loads.', 'A deep centrally, B wide right, C left of centre by ground poles; mannequins and hurdles; keeper.', 'A does 10 sit-ups, passes to B and moves past a mannequin over a hurdle. B does weighted coordination reps, hops two hurdles, rounds a mannequin and plays forward to C. C works through ground poles, rounds a mannequin and lays back for A, who plays wide for B high up the flank. B dribbles on and crosses as A and C run round mannequins into the box to finish.', '2 sets of 6 reps, 3 min rest; rotate A to B to C to A.', NULL, NULL, 'groups of 3 + GK', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Switch play, cross and finish combined', 'finishing', 'unopposed', 'in_possession', 33, 33, 'Speed & Agility WITH a Ball 7', 'Guardiola (Barcelona B)', 'Switching play to the far wing and crossing for two runners, combined with agility.', 'A near the centre circle, a coach out on the right, C by ground poles in the middle, B on the far left touchline by poles; mannequins and hurdles; keeper.', 'B starts with 5 weight reps. A passes to the coach and hops two hurdles; C works through ground poles, rounds a mannequin and receives from the coach, then lays off to A. Meanwhile B sprints up between poles; A switches play long to B high on the flank. B dribbles forward and crosses, A and C attack the box to score.', '2 sets of 3 reps, one set each side; second set distances 15% shorter; rotate A to B to C to A.', NULL, NULL, 'groups of 3 + coach + GK', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Four-station technical interval circuit', 'conditioning', 'passive', NULL, 36, 37, 'Technical Circuits 1', 'Guardiola (Man City)', 'Interval conditioning that mixes technique (dribbling, combinations, shielding) with agility.', 'Four boxed stations around a large area: 1 dribbling through arches past obstacles; 2 cones, a mannequin and pole with positions A, B, C (two copies); 3 coaches with crash pads; 4 hurdles and flat markers.', 'Station 1 dribble through the arches avoiding obstacles. Station 2 A dribbles through cones, 1-2 with B, passes to C, jumps/heads by the mannequin and moves to B, C dribbles through poles. Station 3 receive and shield against a coach pushing with a pad. Station 4 two-footed hurdle jumps, hops on markers, alternate steps over low hurdles. On whistles players go to a red pole, get set, then run at about 85% to another station and walk on to the next.', 'Work 30 s to 1 min per station (coach times it); runs between stations at 85% max speed; rotation run both clockwise and anti-clockwise.', NULL, NULL, 'whole squad in 4 groups', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 190),
  ('Passing, dribbling and finishing speed circuit', 'combination', 'unopposed', 'in_possession', 38, 38, 'Technical Circuits 2', 'Guardiola (Man City)', 'Five-player passing pattern with movement to receive, ending in a shot and a follow-up for rebounds.', 'Half pitch: coach by the goal line with balls, A near him, B wide right, C deep central, D left, E central near the box; hurdles, ground pole, cones, poles and mannequins; keeper.', 'Coach feeds A, who dribbles while B and E move to receive. A passes to C and hops 3 hurdles; B sprints and strides over a ground pole. C comes off his cone to meet the ball and plays to E, who has dropped and passes to D. D checks off his cone, receives and dribbles through poles, then shoots; E follows in for any rebound.', 'Rotate A to B to C to D to E to A.', 'See Technical Circuit 3 for the numbered variation.', 'Movement to get free before receiving; follow shots in.', '5 per group + GK + coach', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Speed circuit variation, ball via B', 'combination', 'unopposed', 'in_possession', 39, 39, 'Technical Circuits 3 (Variation)', 'Guardiola (Man City)', 'Same five-player pattern with a changed passing route through the wide player.', 'As Technical Circuit 2.', 'C passes to B instead of to E; B then plays back to C who has stepped forward off his cone, and the rest of the sequence (E to D, D dribble and shoot, E follows) stays as before. A may also choose to play out wide to B, who then finds C.', 'Rotate A to B to C to D to E to A.', NULL, NULL, '5 per group + GK + coach', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Passing pattern with speed work circuit', 'passing_unopposed', 'unopposed', 'in_possession', 40, 40, 'Technical Circuits 4', 'Guardiola (Man City)', 'Passing pattern with 1-2s and through balls, combined with speed footwork for conditioning.', 'Around the centre circle and edge of the box: A near the box with speed rings and cones, B to the right, C wide right near poles, D in the centre circle; a mannequin and poles.', 'A plays a 1-2 with B, then threads the ball between poles for B to run onto, and A does speed steps through rings and around cones. B passes to C, who has moved in and out of poles and come forward. C plays across to D, who checks away from his cone, receives and dribbles forward, then passes to the next player waiting.', 'Rotate A to B to C to D to A.', NULL, NULL, '4+ per group', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 220),
  ('Fast dribbling and accurate finishing circuit', 'finishing', 'unopposed', 'in_possession', 41, 41, 'Technical Circuits 5', 'Guardiola (Man City)', 'Footwork into dribbling, feinting and a placed finish, then a sprint.', 'Edge of the box: speed rings, 4 hurdles, a mannequin, poles, two coaches (one with balls), a mannequin and poles near the D, cone gate; goal with keeper (or mini goals).', 'Player goes through the rings, jumps 4 hurdles, drops back behind a mannequin and runs on to take the coach''s pass. Dribbles round and through poles, passes across to the second coach and gets it back, then feints past the mannequin and poles as if beating a defender and shoots into a corner. Ends with a sprint through a cone gate.', NULL, 'Mini goals can replace the big goal to force corner placement.', 'Aim for the corners; sell the feint.', 'line of players + 2 coaches + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Press and cover in threes with agility', 'defending', 'passive', 'out_of_possession', 42, 43, 'Technical Circuits 6', 'Guardiola (Bayern Munich)', 'Trios react to the coach''s pass: one steps to the ball, the other two close inside to press and cover.', 'Several groups of 3 on red, yellow and blue cones in a line in front of the coach, who has balls in the middle; hurdles laid out behind.', 'The coach passes to one cone; that player steps forward fast and returns it first time while the other two move across to press and cover. When the ball goes back all three reset to their cones. Repeated with passes to the centre, left and right; after the last one all three sprint to the hurdles, jump them and sprint to halfway.', 'One-touch return pass.', 'Coach varies the ball to the middle, left and right cone so the press/cover shape shifts each time.', 'Quick reaction, close the gap together, recover to shape when the ball goes back.', 'groups of 3 + coach', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 240),
  ('Speed, one-two, dribble and finish', 'finishing', 'unopposed', 'in_possession', 44, 44, 'Technical Circuits 7', 'Guardiola (Bayern Munich)', 'Speed and agility work leading into a one-two, slalom dribble and shot.', 'Near the corner of the box: start cones, yellow and blue cones, two hurdles, ground poles, Player 2 with balls, a line of mannequins; keeper in goal.', 'Player 1 shuttles to the yellow and blue cones and back, jumps forward then sideways over hurdles, jogs, strides through ground poles, sprints to a cone, jogs away and back. Player 2 passes, Player 1 plays a 1-2 and collects round the other side of a mannequin, dribbles in and out of the mannequins and shoots, then sprints to finish.', NULL, NULL, NULL, 'pairs + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Hurdles, one-twos and long-range finish circuit', 'technical', 'unopposed', NULL, 45, 45, 'Technical Circuits 8', 'Guardiola (Man City)', 'Agility plus quick one-two combinations, dribbling and shooting from distance at speed.', 'One half of the pitch: two small hurdles, a line of red mannequins outside the box, three coaches as wall passers, a goal with GK and a yellow cone sprint channel. Half the squad works here while the other half does the circuit in the other half.', 'Coach passes in, player returns it, does two-footed jumps over hurdles, then plays one-twos with Coach 1 and Coach 2, dribbles inside, combines with Coach 3 around a mannequin and shoots from outside the box. Jogs back, sprints the cone channel and jogs to the other half''s circuit.', NULL, NULL, NULL, 'half the squad per circuit plus 3 coaches and GK', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Hurdle jumps, slalom dribble and long shot circuit', 'technical', 'unopposed', NULL, 46, 46, 'Technical Circuits 9', 'Guardiola (Man City)', 'Agility, close dribbling through poles and mannequins, one-two and shooting from outside the box.', 'Other half of the pitch: yellow and blue hurdles, a slalom of yellow poles then red mannequins, two coaches, a mannequin outside the box, goal with GK and a yellow cone channel.', 'Player jumps the yellow hurdle then a blue one, receives from Coach 1, dribbles through poles and mannequins, plays a one-two with Coach 2, beats a mannequin and shoots from outside the area. Jogs, sprints the channel, moves to the other half''s circuit.', NULL, NULL, NULL, 'half the squad per circuit plus 2 coaches and GK', NULL, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Two-goal complex combination and dribble circuit', 'technical', 'unopposed', NULL, 47, 47, 'Technical Circuits 10', 'Guardiola (Man City)', 'Combination play, dribbling under arches and through poles, heading and finishing in two linked circuits.', 'Two circuits side by side facing two goals: cone triangles, arches, yellow poles, red mannequins, hurdles and coaches; players A, B and C in each circuit.', 'Circuit 1: A and B swap a one-two, A takes a coach''s pass, dribbles under two arches and through poles, one-twos with a coach and with C to get in behind mannequins and shoots. Circuit 2: two-footed jumps over hurdles, head back a thrown ball, slalom poles, receive and dribble mannequins, one-two with B and shoot. Players rotate positions and swap circuits.', NULL, NULL, NULL, '3 per circuit plus coaches', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Double circuit: resistance sprints, changes of direction, finish (1)', 'technical', 'unopposed', NULL, 48, 48, 'Technical Circuits 11', 'Guardiola (Bayern Munich)', 'Speed and changes of direction with and without the ball, ending in a one-two and shot.', 'Two mirrored circuits in front of two goals with GKs: resistance band start, cones, mannequins, ground poles, hurdles, poles and a coach in each.', 'Left: 3-second sprint against a partner''s resistance band, run round cones, head a thrown ball, stride through ground poles, receive and dribble poles, one-two with B and shoot past a mannequin. Right: two-footed hurdle jumps, touch mannequin, receive and dribble poles, one-two with B and shoot. B jogs, sprints and jogs to the other side, A takes B''s spot.', NULL, NULL, NULL, '2 groups plus coaches and 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Double circuit: resistance sprints, changes of direction, finish (2)', 'technical', 'unopposed', NULL, 49, 49, 'Technical Circuits 12', 'Guardiola (Bayern Munich)', 'Acceleration and sharp changes of direction, combining with coaches and finishing from distance.', 'Two circuits each ending at a goal with GK: resistance band start, three cones, poles, hurdles, mannequins and two coaches.', 'Left: band sprint, run round cones and a pole to receive, dribble the cones, pass to Coach 1, touch 2-4 poles with sharp turns, receive, one-two with Coach 2 round a mannequin and shoot from outside the box. Right: band sprint, hurdle jumps, round a pole to receive, one-two through poles, dribble poles and mannequins and shoot. Jog-sprint-jog to the other side.', NULL, NULL, NULL, '2 groups plus coaches and 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Speed and agility circuits finishing both ends', 'technical', 'unopposed', NULL, 50, 50, 'Technical Circuits 13', 'Guardiola (Bayern Munich)', 'Footwork, agility and dribbling into shots, plus crossing and finishing a team-mate''s cross.', 'Two circuits across the pitch toward goals at each end with GKs: speed rings, hurdles, poles, mannequins and coaches.', 'Left: pause in rings, step over hurdles, touch mannequin, run round poles, take coach''s pass, dribble past a mannequin and shoot; then sprint, head a thrown ball, step over hurdles, receive and cross for the opposite side. Right: hurdle jumps, touch mannequin and poles, dribble and shoot, then one-twos with the coach and attack the cross from the other side.', NULL, NULL, NULL, '2 groups plus coaches and 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Short passing, dribbling and finish double circuit', 'technical', 'unopposed', NULL, 51, 51, 'Technical Circuits 14', 'Guardiola (Bayern Munich)', 'Short one-two combinations, movement around mannequins, dribbling and finishing.', 'Two mirrored circuits near the centre circle toward two goals with GKs: mannequins, cones, poles and a coach; players A and B.', 'A and B swap one-twos while B touches and runs around mannequins; B then receives from the coach, dribbles through cones and poles, past mannequins and shoots. B jogs, sprints through cones and sprints to start on the opposite side.', NULL, NULL, NULL, 'pairs in 2 circuits plus coach and 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Speed circuits with through ball and finish', 'technical', 'unopposed', NULL, 52, 52, 'Technical Circuits 15', 'Guardiola (Bayern Munich)', 'Footwork into a passing combination and a timed run onto a long through ball to finish.', 'Middle third and penalty area: speed rings, hurdles, yellow and blue poles, a coach, goal with GK; Player A (red) and Player B (yellow).', 'After ring and hurdle footwork, coach feeds A, A plays B, B returns (one-two) and runs through poles; A combines with the coach through blue poles, then plays a long diagonal pass (ground or air) for B to sprint onto, enter the box and score. Both sprint to the other side.', NULL, 'Long pass can be lofted in behind.', NULL, 'pairs plus coach and GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 330),
  ('Speed circuits with one-touch passing and finish', 'technical', 'unopposed', NULL, 53, 53, 'Technical Circuits 16', 'Guardiola (Bayern Munich)', 'Agility work combined with quick one-touch passing, dribbling and press-and-cover movement.', 'Two identical wide circuits plus a middle circuit with mannequins; poles, hurdles, speed rings, resistance bands, a coach and a goal with GK.', 'Wide: one-twos with the coach around a mannequin and poles, dribble through poles, pass across to a team-mate who dribbles into the box and passes to the coach. Middle: sideways steps over hurdles, then press-and-cover movements as the coach passes to mannequins, then a one-two between mannequins to get in behind and score. Players jog to a wide circuit.', NULL, NULL, NULL, 'groups in 3 circuits plus coach and GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Three speed, coordination and agility ball circuits', 'technical', 'unopposed', NULL, 54, 54, 'Technical Circuits 17', 'Guardiola (Bayern Munich)', 'Coordination and speed work leading into dribbling, one-twos and shots in three rotating circuits.', 'Three circuits A, B, C side by side, each ending at a goal with GK: resistance band, hurdles, poles, speed rings, mannequins and coaches.', 'A: band sprint, hurdle jumps, touch poles, one-two with coach, dribble between mannequins and shoot. B: sideways hurdle jumps into rings, receive and dribble in and out of poles, one-two with Pep, dribble past mannequin and shoot. C: hops through rings, slalom poles, high knees, one-two with coach, slalom mannequins and shoot. Jog-sprint-jog to the next circuit.', NULL, NULL, NULL, '3 groups plus coaches and 3 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Power and agility circuit plus 3v2 duel', 'technical', 'opposed', 'in_possession', 55, 55, 'Technical Circuits 18', 'Guardiola (Bayern Munich)', 'High-intensity speed and power work feeding a feint-and-shoot finish and a 3v2 attack using overlaps and underlaps.', 'Three zones each with a large goal and GK; two identical wide zones with resistance band, hurdles, poles and mannequins; middle zone for 3v2. Teams A, B, C rotate.', 'Wide: high knees on the spot against a band for 5 seconds, sideways then forward hurdle jumps, receive and roll the ball under a hurdle, dribble poles, attack mannequins with a feint and shoot, then join C as defenders. Middle: C passes to A and steps out to defend 3v2; A try to score. A move to the wide zones, C move up to attack.', NULL, NULL, 'Use underlapping or overlapping runs in the 3v2.', '3 teams plus coaches and 3 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 360),
  ('3v1 keep-ball, lay-off and through ball to mini goal', 'passing_opposed', 'passive', 'in_possession', 58, 59, 'Man City Passing Practices 1-2', 'Guardiola (Man City)', 'Keep the ball under pressure, then a third-man lay-off and a final pass in behind for a timed run and first-time finish.', 'A small grid where 3 players keep the ball against a coach; in front, players A, B, C and D around cones, a red mannequin and a mini goal.', 'Three keep it 3v1 against the coach; after a few passes the furthest-forward one lays off and the team-mate plays forward to A. A chooses to lay it back to B or C, who plays beyond the mannequin for D to run onto and finish first time in the mini goal. All rotate.', 'Finish first time.', 'Practice 2: same pattern but A lays off to C, who plays the final pass.', 'A reads which side to lay off to; D times the forward run.', '3v1 plus 4', 7, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 370),
  ('3v1 keep-ball into chipped pass and run in behind', 'passing_opposed', 'passive', 'in_possession', 60, 62, 'Man City Passing Practices 3-5', 'Guardiola (Man City)', 'Keep the ball, then a lay-off sequence ending in a chipped pass over mannequins for a run in behind to score between poles.', '3v1 grid with a station either side, then a channel with players C, D, E, F, two mannequins and two poles as a goal at the far end.', '3v1 against the coach; C lays back to A, A plays to E who drops, E lays off to F, F chips over for D, who first drops then runs in behind to score between the poles. All rotate.', NULL, 'Practice 4: E lays off to D, D passes across to F, F chips for D. Practice 5: A plays to D, D across to F, F to E, E lays back to F who chips for D.', 'D checks back before the run in behind; well-timed run.', '3v1 plus 6', 10, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 380),
  ('Passing, receiving and turning circuit', 'passing_unopposed', 'unopposed', NULL, 63, 63, 'Man City Passing Practices 6', 'Guardiola (Man City)', 'Passing, receiving on the move, turning with the ball and dribbling through poles.', 'Around the centre circle: players A, B, C at cones, poles and a cone triangle.', 'A to B who drops, B passes across for A to run onto, A plays to C moving across, C finds B who has circled a cone, B turns and dribbles through poles then passes to the start for the next player.', NULL, NULL, NULL, '3+ in rotation', 3, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 390),
  ('Pass and move circuit with speed work', 'passing_unopposed', 'unopposed', NULL, 65, 65, 'Bayern Munich Passing Practices 1', 'Guardiola (Bayern Munich)', 'Pass and move to receive, combined with sprinting and hurdle work.', 'Rectangle with poles, mannequins and hurdles; players A to E at stations.', 'A-B one-two, B runs round a pole; A plays wide to C, C inside to B, B forward to D, D to E, E back inside to D, D plays in front of a mannequin for E then sprints, jumps two hurdles and rounds a pole; E dribbles past a mannequin back to start. Rotate A to B to C to D to E.', NULL, NULL, NULL, '5+', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 400),
  ('One-touch passing diamond with timed movement', 'passing_unopposed', 'unopposed', NULL, 66, 67, 'Bayern Munich Passing Practices 2-3', 'Guardiola (Bayern Munich)', 'Short and medium one-touch passing with well-timed movement around mannequins and poles.', 'Two diamonds of 8 players working at the same time near the box, with mannequins and poles; positions A, B, C, D.', 'A to B in front of a mannequin, back to A, A to C behind the mannequin, C lays off for B, B across to D, D lays off for C, C plays the final pass for D running round pole and mannequin; D dribbles back to start. Rotate A to B to C to D.', 'Mostly one touch.', 'Practice 3 variations: B takes 1-2 touches and passes straight to D; or B plays back to C who passes to D.', NULL, '2 groups of 8', 8, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 410),
  ('Double one-two combination, run in behind, finish', 'combination', 'unopposed', 'in_possession', 68, 68, 'Bayern Munich Passing Practices 4', 'Guardiola (Bayern Munich)', 'Short passing combination with double one-two ending with a run in behind and a finish.', 'Two groups of 8 working at once in front of two goals: mannequins, hurdles and cones; positions A, B, C, D.', 'A to D and back as A moves up; D jumps two hurdles; A to C, A side-steps through mannequins; C lays off to B, B returns to C, C plays the final ball for B running round a mannequin to score. Rotate.', 'Mostly one touch.', NULL, NULL, '2 groups of 8', 8, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Lay-off combination and shot from distance', 'combination', 'unopposed', 'in_possession', 69, 69, 'Bayern Munich Passing Practices 5', 'Guardiola (Bayern Munich)', 'Showing to receive and lay-offs to set up a shot from outside the box.', 'Outside the penalty area: poles and cones, players A, B, C, D, goal with GK.', 'A to B who drops, back to A, A to C moving across, C to B who runs round pole and cone, B to D, D lays back for C to shoot from outside the area. Rotate.', NULL, NULL, NULL, '4+ plus GK', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Double one-two and shot outside the box', 'combination', 'unopposed', 'in_possession', 70, 70, 'Bayern Munich Passing Practices 6', 'Guardiola (Bayern Munich)', 'Double one-two combination to release a runner for a long-range shot.', 'Edge of the box: a coach, a mannequin, cones, players A, B, C and a goal with GK.', 'A one-twos with the coach, plays to C, C plays back diagonally for B coming off a cone, B passes beside the mannequin to C, C slips it in front of the mannequin for B to shoot from outside the area. Rotate.', NULL, NULL, NULL, '3+ plus coach and GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Combination round the box and finish', 'combination', 'unopposed', 'in_possession', 71, 71, 'Bayern Munich Passing Practices 7', 'Guardiola (Bayern Munich)', 'Combination play around the area with a well-timed run into the box to score.', 'Around the penalty area: cones for A, B and C, goal with GK.', 'A passes to B who comes off at an angle, B plays to C who drops off a cone, C slides the ball into the area around the penalty spot for A, who has timed a run in, to finish. Rotate A to B to C.', NULL, NULL, NULL, '3+ plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Opening up to receive passing square', 'passing_unopposed', 'unopposed', NULL, 74, 76, 'Barcelona Passing Practices 1-3', 'Guardiola (Barcelona B)', 'Opening the body to receive and pass on, then one-twos and short/medium combinations around a square.', '30 x 30m square with a player at each corner (A, B, C, D), extra players queue at A.', 'Ball goes round the square; each receiver opens up and passes on with one touch to receive and one to pass. Rotate A to B to C to D.', 'Receive and open up with 1 touch then pass.', 'Practice 2: B returns a one-two to A, then A plays again to B on the move; repeat at each side. Practice 3: one-twos then diagonal passes across the square (A-B one-two, A to C, C back to B, B to D, D back to C). 3 minutes each.', 'Open up on the first touch.', '4+', 4, NULL, '30 x 30m', 30.0, 30.0, 9.0, false, false, false, NULL, 460),
  ('One-two and move passing triangle', 'passing_unopposed', 'unopposed', NULL, 77, 78, 'Barcelona Passing Practices 4-5', 'Guardiola (Barcelona B)', 'One-twos and passes into space for team-mates to run onto, around a triangle.', 'Triangle of cones, players at A (queue), B and C.', 'A to B, B returns for A to run onto, A plays in front of B, B to C, C lays back, B plays in front of C, C passes to the start. Rotate A to B to C.', NULL, 'Practice 5: A-B one-two, A to C, C lays back for B, B to start. Each group takes 3 turns anti-clockwise and 3 clockwise.', NULL, '3+', 3, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 470),
  ('Passing Y with timed movements', 'passing_unopposed', 'unopposed', NULL, 79, 79, 'Barcelona Passing Practices 6', 'Guardiola (Barcelona B)', 'Short and medium combination play with well-timed movement around mannequins.', 'Y shape: A1/A2 at the base, B1/B2 in the middle, C and D wide with a mannequin each.', 'A1 plays B1, one-two, A1 to C, C lays back for B1, B1 plays in front of the mannequin for C to run onto; then the same down the other side with A2, B2 and D. Rotate A to B to C to D.', NULL, 'C/D dribble back to the start; or C/D dribble and try to score in a mini goal or big goal with GK.', NULL, '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 480),
  ('Movement to receive passing rectangle', 'passing_unopposed', 'unopposed', NULL, 80, 82, 'Barcelona Passing Practices 7-9', 'Guardiola (Barcelona B)', 'Moving across to receive, with aerial passes, overlap runs and complex short combinations.', 'Rectangle with cones on each side; A at the base, B and C on opposite side cones, D at the far end.', 'A to C who moves across, C to B who also moves across, B to D coming diagonally off his cone, D plays an aerial ball back to the start. Rotate. Each player does 6 repetitions then rests 2 minutes.', NULL, 'Practice 8: A starts with an aerial ball to D; D to B, B to C, C plays D in after an overlap on the outside. Practice 9: longer short-pass combination (A-C-B-D-C-D-B-C) with D overlapping to receive and finishing back to A.', NULL, '4+', 4, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 490),
  ('Receive, dribble forward and long shot', 'finishing', 'unopposed', 'in_possession', 83, 85, 'Barcelona Passing Practices 10-12', 'Guardiola (Barcelona B)', 'Receive on the run, drive forward at speed and shoot from outside the box.', 'Two mirrored stations either side of centre, 25+ yards out; cones for A, B, C; goal with GK.', 'A to B, B to C who comes off a cone, C dribbles at speed and shoots from outside the area. Rotate. 2 repetitions per side.', NULL, 'Practice 11: A-B one-two, A plays B across, B to C, C dribbles and shoots. Practice 12: A-B one-two, A to C, C plays B across, B plays in front of C who runs onto it and shoots.', NULL, '3+ per side plus GK', 7, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 500),
  ('3v1 ground and aerial triangle rondos', 'rondo', 'opposed', 'in_possession', 88, 88, 'Rondos 1', 'Guardiola (Man City)', 'One-touch passing warm-up, ball juggling and aerial passing, then a live 3v1 rondo.', 'Groups of 4: triangle with outside players about 4-5 yards apart and one in the middle.', 'Stage 1: middle player passes one touch to outside players or plays one-twos, direction changing, swapping roles. Stage 2: aerial rondo using 3 touches (two juggles and an aerial pass). Stage 3: normal 3v1 ground rondo.', 'Stage 1 one touch; Stage 2 exactly 3 touches where possible (1-2 if not); Stage 3 mainly one touch.', 'Stages 1 to 3 as listed.', NULL, '3v1 (groups of 4)', 4, 4, 'triangle 4-5 yards a side', 4.1, 4.1, NULL, false, false, false, NULL, 510),
  ('4v2 square rondo, one per side', 'rondo', 'overload', 'in_possession', 89, 89, 'Rondos: 2. 4 v 2 Square Rondo', 'Guardiola (Barcelona B)', 'Quick one-touch circulation round two pressing defenders.', 'Groups of 6 in a 10 x 10 yard square: one attacker on each side (outside the line but playing inside the box), 2 defenders in the middle.', 'The four outside players keep the ball away from the two middle players, who work as a pair to shut passing angles and win it.', 'Aim for one touch. Whoever gives the ball away swaps places with the defender who won it.', NULL, 'Defenders press together to close angles.', '4v2', 6, 6, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 520),
  ('4v2 narrow rectangle rondo', 'rondo', 'overload', 'in_possession', 90, 90, 'Rondos: 3. 4 v 2 Rectangle Rondo', 'Guardiola (Man City)', 'Keeping the ball in a long thin area, with side players moving to open angles.', 'Groups of 6 in a 3 x 10 yard strip: one attacker per side, 2 defenders inside.', 'Four outside players keep possession; the two on the long sides shuttle up and down to offer angles to the end players while the two inside defenders press.', 'Mostly 1-2 touches. Whoever gives the ball away swaps places with the defender who won it.', NULL, 'Side players keep moving to give support angles.', '4v2', 6, 6, '3 x 10 yards', 9.1, 2.7, NULL, false, false, false, NULL, 530),
  ('5v2 square rondo', 'rondo', 'overload', 'in_possession', 92, 92, 'Rondos: 4. 5 v 2 Square Rondo', 'Guardiola (Man City)', 'One-touch keep-ball with an extra outside player.', 'Groups of 7 in a 10 x 10 yard square: two attackers on one side, one on each other side, 2 defenders inside.', 'Five outside players keep the ball from the two inside, who press as a pair to close angles and win it.', 'Aim for one touch. Whoever gives the ball away swaps places with the defender who won it.', NULL, 'Defenders work together to cut angles.', '5v2', 7, 7, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 540),
  ('6v2 tight rectangle rondo', 'rondo', 'overload', 'in_possession', 93, 93, 'Rondos: 5. 6 v 2 Rectangle Rondo', 'Guardiola (Man City)', 'One-touch possession in a very tight rectangle with side players creating angles.', 'Groups of 8 in a 5 x 10 yard rectangle: two attackers on each short side, one on each long side, 2 defenders inside.', 'Six outside players keep the ball; the long-side players move up and down to give the ends angles, while the inside pair press.', 'Aim for one touch. Whoever gives the ball away swaps places with the defender who won it.', NULL, 'Side players constantly move to open angles.', '6v2', 8, 8, '5 x 10 yards', 9.1, 4.6, NULL, false, false, false, NULL, 550),
  ('7v2 square rondo', 'rondo', 'overload', 'in_possession', 94, 94, 'Rondos: 6. 7 v 2 Square Rondo', 'Guardiola (Man City)', 'One-touch circulation with a big overload round two defenders.', 'Groups of 9 in a 10 x 10 yard square: two attackers on three sides, one on the fourth, 2 defenders inside.', 'Seven outside players keep possession while the two inside defenders work together to cut angles and win the ball.', 'Aim for one touch. Whoever gives the ball away swaps places with the defender who won it.', NULL, NULL, '7v2', 9, 9, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 560),
  ('3v3+2 possession and transition game', 'possession', 'overload', 'to_defend', 98, 98, 'Juego de Posicion: 1. High Intensity 3 v 3 (+2) Possession and Transition Game', 'Guardiola (Bayern Munich)', 'Keeping the ball with joker support and counter-pressing straight after losing it.', '12 x 12 yard square; blues have one player at each end and one inside, all 3 reds start inside, and a yellow joker sits on each side for the team in possession.', 'Coach (or a joker) starts it; blues keep the ball with the jokers while the reds press. If reds win it, roles flip: blues all come inside to counter-press and reds spread to the outside (2 at the ends, 1 in the middle).', 'Jokers play with the team in possession and can be challenged.', NULL, 'Press as a unit to shut angles; win it back at once after a loss.', '3v3+2', 8, 8, '12 x 12 yards', 11.0, 11.0, NULL, false, false, false, NULL, 570),
  ('4v4+2 possession and transition game', 'possession', 'overload', 'to_defend', 99, 99, 'Juego de Posicion: 2. High Intensity 4 v 4 (+2) Possession and Transition Game', 'Guardiola (Barcelona B)', 'High-tempo possession with immediate counter-press on losing the ball.', '15 x 20 yard area; 4 blues on the sides, 4 reds inside, one yellow joker on a side and one inside.', 'Blues keep the ball with the two jokers; reds press. When reds win it, blues all step inside to win it back and reds move to the outside to keep possession.', 'Max 2 touches. Jokers play for the team in possession and can be challenged.', NULL, 'Very high pace; target heart rate around 120 bpm.', '4v4+2', 10, 10, '15 x 20 yards', 18.3, 13.7, 28.0, false, false, false, NULL, 580),
  ('5+2v3 possession game', 'possession', 'overload', 'in_possession', 100, 100, 'Juego de Posicion: 3. 5 (+2) v 3 Possession Game', 'Guardiola (Bayern Munich)', 'Keeping possession with an outside overload and two inside jokers.', '10 x 15 yard area; 5 reds on the sides (two on one short side), 3 blues start inside, 2 yellow jokers inside.', 'Reds keep the ball with help from the jokers while the three blues press to cut angles and win it.', 'The blue who wins the ball swaps with the red who lost it; play goes on.', NULL, NULL, '5v3+2', 10, 10, '10 x 15 yards', 13.7, 9.1, NULL, false, false, false, NULL, 590),
  ('6+2v3 possession game', 'possession', 'overload', 'in_possession', 101, 101, 'Juego de Posicion: 4. 6 (+2) v 3 Possession Game', 'Guardiola (Man City)', 'Possession with a 6-player outside ring plus two inside jokers against three pressers.', '15 x 15 yard square; 6 blues on the sides (two on each long side), 3 reds inside, 2 yellow jokers inside.', 'The 6 outside blues and the 2 jokers keep the ball while the 3 reds inside press as a group to cut angles and win it.', 'The defender who wins the ball swaps with the player who lost it.', NULL, NULL, '6v3+2', 11, 11, '15 x 15 yards', 13.7, 13.7, NULL, false, false, false, NULL, 600),
  ('4v4+3 possession and transition game', 'possession', 'overload', 'to_defend', 102, 102, 'Juego de Posicion: 5. 4 v 4 (+3) Possession and Transition Game', 'Guardiola (Man City)', 'Possession with three jokers and an instant team-wide counter-press on loss.', '10 x 15 yard area; 4 blues on the long sides (two each), 4 reds inside, yellow jokers at each end and one inside.', 'Coach serves to the blues, who keep it with the jokers while reds press. When reds win it, the teams swap: blues come inside to counter-press, reds go to the outside.', 'Jokers play for the team in possession and can be challenged.', NULL, 'Coach constantly instructs and encourages.', '4v4+3', 11, 11, '10 x 15 yards', 13.7, 9.1, NULL, false, false, false, NULL, 610),
  ('5v5+3 possession and transition game', 'possession', 'overload', 'to_defend', 103, 103, 'Juego de Posicion: 6. 5 v 5 (+3) Possession and Transition Game', 'Guardiola (Man City)', 'Possession and quick reaction on loss, with one player per team staying central.', '20 x 20 yard square; blues have two on each long side and one inside, all 5 reds inside, jokers at each short end and one inside.', 'Blues keep the ball with three jokers while reds press. On a red win, 4 reds swap with the 4 outside blues; those blues come in to win it back.', 'One player from each team stays in the middle throughout. Jokers play for the team in possession.', NULL, NULL, '5v5+3', 13, 13, '20 x 20 yards', 18.3, 18.3, NULL, false, false, false, NULL, 620),
  ('6v6+4 possession and transition game', 'possession', 'overload', 'to_defend', 104, 104, 'Juego de Posicion: 7. 6 v 6 (+4) Possession and Transition Game', 'Guardiola (Bayern Munich)', 'Larger possession game with four jokers and instant counter-press.', '20 x 30 yard area; 4 reds on the long sides plus 2 inside, all 6 blues inside, a yellow joker at each end and 2 inside.', 'Coach serves to the reds, who keep it with the jokers while blues press. On a blue win, 4 blues swap to the outside and the 4 outside reds come in to counter-press.', 'Two players from each team stay in the middle throughout.', NULL, NULL, '6v6+4', 16, 16, '20 x 30 yards', 27.4, 18.3, NULL, false, false, false, NULL, 630),
  ('8v8+3 possession and transition game', 'possession', 'overload', 'to_defend', 105, 105, 'Juego de Posicion: 8. 8 v 8 (+3) Possession and Transition Game', 'Guardiola (Man City)', 'Big-group positional possession with roles flipping on every turnover.', '30 x 40 yard area; 5 blues on the sides (two at one end) and 3 inside, all 8 reds inside, a yellow joker on each side and one inside.', 'Blues keep the ball with three jokers while reds press. When reds win it, 5 reds swap to the outside with the 5 outside blues, who come inside to win it back.', 'Three players from each team stay in the middle throughout.', NULL, NULL, '8v8+3', 19, 19, '30 x 40 yards', 36.6, 27.4, NULL, false, false, false, NULL, 640),
  ('Three-team possession with aerial switch', 'transition', 'overload', 'to_defend', 106, 107, 'Juego de Posicion: 9. Three Team Possession and Fast Transition Game', 'Guardiola (Bayern Munich)', 'Possession under pressure, switching play long and fast transitions between zones.', '15 x 45 yards split into two 15 x 10 end zones and a 15 x 25 middle zone; three teams (red, blue, grey) plus a joker; greys wait in the middle zone.', 'Coach serves to reds in one end; 2 greys enter to make 6(+1)v2. Reds string 6-8 passes then switch with a lofted ball to the blues in the far end, where 2 new greys press. If greys win it they swap with the team that lost it; coach restarts and the losing team sends 2 across to defend.', 'Middle greys can leave their zone to cut out the aerial pass. 6-8 passes before switching.', NULL, 'Continuous high-intensity transitions.', '3 teams of 6 + 1 joker', 19, 19, '15 x 45 yards', 41.1, 13.7, NULL, false, false, true, NULL, 650),
  ('7v7+3 possession through pole gates', 'positional_game', 'overload', 'in_possession', 108, 108, 'Juego de Posicion: 10. 7 v 7 (+3) Possession Game with Pole Gates', 'Guardiola (Man City)', 'Keeping the ball while finding a team-mate through small gates.', 'Around the centre circle area with several pole gates spread inside; two teams of 7 plus jokers.', 'Coach serves to blues, who keep possession with the jokers and score by passing through a pole gate to a team-mate. On a turnover the reds take over with the same aims.', 'Point each time a pass through the poles is received.', NULL, NULL, '7v7+3', 17, 17, NULL, NULL, NULL, NULL, false, false, true, NULL, 660),
  ('Two-zone 8v6 win it and switch play', 'transition', 'overload', 'to_attack', 109, 109, 'Juego de Posicion: 11. Win the Ball and Switch the Play in a Two Zone 8 v 8 Possession and Transition Game', 'Guardiola (Barcelona B)', 'Winning the ball and switching quickly to the other zone, with the losers counter-pressing.', 'Pitch split into two halves (zones); 8 blues and 8 yellows, 6 yellows pressing in the blue zone and 2 yellows waiting in the other half.', 'Coach serves to blues who keep it 8v6. When yellows win it they pass quickly to their two team-mates in the other half while blues press to win it straight back. If the switch works, all but two yellows move across and it becomes 8v6 the other way.', NULL, NULL, NULL, '8v8', 16, 16, NULL, NULL, NULL, 45.0, false, false, false, NULL, 670),
  ('9v9+2 inside jokers possession game', 'possession', 'overload', 'to_defend', 110, 110, 'Juego de Posicion: 12. 9 v 9 (+2 Inside) Possession Game', 'Guardiola (Barcelona B)', 'Large possession game with two inside jokers and fast reaction on losing it.', '30 x 40 yard area; two teams of 9 plus 2 red jokers playing inside.', 'Coach serves to blues who keep it with the jokers while yellows press. On a turnover roles switch and the side that lost it tries to win it back immediately.', 'Jokers play for the team in possession.', NULL, NULL, '9v9+2', 20, 20, '30 x 40 yards', 36.6, 27.4, NULL, false, false, false, NULL, 680),
  ('9v9+2 outside jokers possession game', 'possession', 'overload', 'to_defend', 111, 111, 'Juego de Posicion: 13. 9 v 9 (+2 Outside) Possession Game', 'Guardiola (Barcelona B)', 'Large possession game using two outside jokers, with quick transition on loss.', '30 x 40 yard area; two teams of 9 inside, 2 red jokers on the outside (one each end).', 'Coach serves to blues who keep it using the outside jokers while yellows press; on a turnover roles reverse and the losers win it back fast.', 'Jokers play for the team in possession.', NULL, NULL, '9v9+2', 20, 20, '30 x 40 yards', 36.6, 27.4, NULL, false, false, false, NULL, 690),
  ('Full back receives lay-off and drives forward', 'combination', 'passive', 'in_possession', 117, 118, 'Attacking Patterns: 1. Full Back Moves Forward to Receive Attacking Midfielder''s Lay-off and Dribble Forward into the Final Third', 'Guardiola (Man City)', 'Build-up pattern using the half space so an inverted full back can carry the ball forward.', 'Full half pitch in Man City''s 4-3-3 with inverted full backs; 6 mannequins and 5 passive red defenders; 2 players per position (two teams of 10) alternate; coaches with balls on each side start it by serving a centre back; keeper in goal.', 'Right CB passes across to left CB; left No.8 comes inside and lays it back to the advancing left back in the half space; he dribbles on and switches to the right No.8, who slips the striker in behind on a curved run while winger and other No.8 also run beyond; striker shoots.', 'Teams take turns; jog back after each run.', NULL, 'Curved runs away from the defender; arrive in the half space.', '2 x 10 outfield + GK', 21, 23, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 700),
  ('Lay-off for holding mid''s pass in behind', 'combination', 'passive', 'in_possession', 119, 119, 'Attacking Patterns: 2. Attacking Midfielder''s Lay-off for the Defensive Midfielder''s Pass in Behind to the Forward', 'Guardiola (Man City)', 'Third-man combination through the No.6 to play the striker in.', 'Full half pitch in Man City''s 4-3-3 with inverted full backs; 6 mannequins and 5 passive red defenders; 2 players per position (two teams of 10) alternate; coaches with balls on each side start it by serving a centre back; keeper in goal.', 'Right CB to right back in the half space; right back finds the left No.8 who has drifted central; he lays back to the No.6 on a curved forward run, who threads it to the striker running off his marker; winger and No.8 also run in behind; striker shoots.', 'Teams alternate.', NULL, NULL, '2 x 10 outfield + GK', 21, 23, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 710),
  ('Long pass to striker, third-man run beyond', 'combination', 'passive', 'in_possession', 120, 120, 'Attacking Patterns: 3. Centre Back''s Long Pass to the Forward + Pass in Behind for Attacking Midfielder''s Third Man Run', 'Guardiola (Man City)', 'Playing direct into the striker''s feet and finding a deep third-man runner.', 'Full half pitch in Man City''s 4-3-3 with inverted full backs; 6 mannequins and 5 passive red defenders; 2 players per position (two teams of 10) alternate; coaches with balls on each side start it by serving a centre back; keeper in goal.', 'Right CB to left CB while the left No.8 drops to offer; left CB drives a long pass into the striker''s feet as the No.6 steps up; striker plays the right No.8 in on a curved run from deep; he shoots.', 'Teams alternate.', NULL, 'Time the third-man run from deep.', '2 x 10 outfield + GK', 21, 23, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 720),
  ('Switch play and overlap to cross', 'combination', 'passive', 'in_possession', 121, 121, 'Attacking Patterns: 4. Switching the Point of Attack and Passing in Behind to the Full Back on the Overlap', 'Guardiola (Man City)', 'Switching the point of attack and releasing the overlapping full back to cross.', 'Full half pitch in Man City''s 4-3-3 with inverted full backs; 6 mannequins and 5 passive red defenders; 2 players per position (two teams of 10) alternate; coaches with balls on each side start it by serving a centre back; keeper in goal.', 'Left CB to left back in the half space and back; CB finds the No.6, who switches to the other CB; he steps up and feeds the right winger coming off the line; winger lays off to the right No.8, who plays the right back in behind on the overlap; he crosses for 4 runners and the striker heads in.', 'Teams alternate.', NULL, NULL, '2 x 10 outfield + GK', 21, 23, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 730),
  ('High-tempo 5v5 with full goals', 'small_sided_game', 'opposed', NULL, 123, 123, 'Small Sided Games: 1. High Tempo 5 v 5 Small Sided Game with Large Goals', 'Guardiola (Man City)', 'Playing fast with few touches in a small game to big goals.', 'Small pitch with two full-size goals and keepers; 5v5.', 'Normal 5v5; keeper starts each attack and can distribute short, medium or long.', '1-3 touches. Ball out of play restarts from the keeper.', NULL, 'High tempo.', '5v5 + 2 GKs', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 740),
  ('Three-team 7v7 with 6 outside supports', 'small_sided_game', 'overload', NULL, 124, 124, 'Small Sided Games: 2. Three Team 7 v 7 (+6) Small Sided Game', 'Guardiola (Barcelona B)', 'Using an overload of outside players to move the ball forward fast and score.', 'Pitch with two full goals and keepers; two teams of 7 play inside, the resting third team (6) stands round the outside supporting the side in possession.', 'Keeper always starts play; team on the ball uses the outside players to progress quickly and score. 8-minute games, then rotate.', 'Ball out restarts from the keeper.', 'Rotate the outside team every 45 seconds for more intensity; or winner stays on - team that concedes swaps with the outside team.', NULL, '7v7+6 + 2 GKs', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 750),
  ('High-tempo 7v7+1 with full goals', 'small_sided_game', 'overload', NULL, 125, 125, 'Small Sided Games: 3. High Tempo 7 v 7 (+1) Small Sided Game with Large Goals', 'Guardiola (Man City)', 'Fast play with a joker overload to create chances.', 'Pitch with two full goals and keepers; 7v7 plus one joker.', 'Normal game; keeper starts each attack (short, medium or long), team in possession uses the joker''s extra man to score.', '1-3 touches. Ball out restarts from the keeper.', NULL, NULL, '7v7+1 + 2 GKs', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 760),
  ('Three-zone 10v9 build up with overloads', 'phase_of_play', 'overload', 'in_possession', 126, 126, 'Small Sided Games: 4. Creating a Numerical Advantage and Progressing Attacks in a 3 Zone Game', 'Guardiola (Barcelona B)', 'Building up through thirds by stepping a player forward to create an extra man.', 'Half pitch across its width, split into 3 equal zones with a goal at each end; 4v3 in the low zone, 2v2 middle, 3v3 end zone (10v9 with keeper).', 'Keeper starts; blues build 4v3 and pass into the middle zone, then one player steps up to make 3v2; they pass into the end zone and one more steps up to make 4v3 and score.', 'Only one player may move up a zone after each successful pass forward.', NULL, NULL, '10v9', 19, 22, 'Half pitch, 3 zones', NULL, NULL, NULL, true, true, true, NULL, 770),
  ('Positional 9v7 attacking three goals', 'phase_of_play', 'overload', 'in_possession', 127, 127, 'Small Sided Games: 5. Positional 9 v 7 (+3 GKs) Game with 3 Goals', 'Guardiola (Bayern Munich)', 'Building up and playing in behind against a compact block that must shift to guard three goals.', 'Half pitch with 3 full goals and keepers on the end line; reds 9 in a 3-3-3, yellows 7 in a compact 4-3.', 'Coach serves to reds, who build up, try to get in behind and score in any goal; yellows defend all three and try to win it.', 'If yellows or a keeper win it, the ball goes out or reds score, coach restarts with a new ball to reds.', NULL, 'Three goals make the defence shift more and open lanes.', '9v7 + 3 GKs', 19, 19, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 780)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'pep-guardiola-85-passing-rondos-possession-games-technical-circuits-direct-from-') b;
